import React, {
  useEffect,
  useMemo,
  useState
} from "react";

import axios from "axios";

import {
  useLocation,
  NavLink,
  useNavigate
} from "react-router-dom";

import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import { QRCodeCanvas } from "qrcode.react";

import Navbar from "../../components/Navbar/Navbar";
import Footer from "../../components/Footer/Footer";

import { API_URL } from "../../api";

import { useLanguage } from "../../context/LanguageContext";

import "./Confirmation.css";


function Confirmation() {

  const navigate = useNavigate();
  const location = useLocation();

  const { t } = useLanguage();


  // =========================================
  // TEMPORARY CONFIRMATION STORAGE KEY
  // =========================================

  const CONFIRMATION_STORAGE_KEY =
    "busgo_confirmation_booking";

  const TICKET_STORAGE_KEY =
    "busgo_confirmation_ticket";


  // =========================================
  // BOOKING DATA
  // =========================================

  const [booking, setBooking] = useState(() => {

    if (location.state) {
      return location.state;
    }

    try {

      const savedBooking =
        sessionStorage.getItem(
          CONFIRMATION_STORAGE_KEY
        );

      if (!savedBooking) {
        return null;
      }

      return JSON.parse(savedBooking);

    } catch (error) {

      console.error(
        "Unable to restore confirmation booking:",
        error
      );

      return null;

    }

  });


  // =========================================
  // TICKET NUMBER
  // =========================================

  const [ticketNumber] = useState(() => {

    try {

      const savedTicket =
        sessionStorage.getItem(
          TICKET_STORAGE_KEY
        );

      if (savedTicket) {
        return savedTicket;
      }

    } catch (error) {

      console.error(
        "Unable to restore ticket number:",
        error
      );

    }

    const generatedTicket =
      "BG-" +
      Math.floor(
        100000 +
        Math.random() * 900000
      );

    try {

      sessionStorage.setItem(
        TICKET_STORAGE_KEY,
        generatedTicket
      );

    } catch (error) {

      console.error(
        "Unable to save ticket number:",
        error
      );

    }

    return generatedTicket;

  });


  // =========================================
  // SAVING STATE
  // =========================================

  const [saving, setSaving] =
    useState(false);


  // =========================================
  // CONFIRMATION SUCCESS
  // =========================================

  const [confirmed, setConfirmed] =
    useState(false);


  // =========================================
  // SAVE BOOKING TO SESSION STORAGE
  // =========================================

  useEffect(() => {

    if (!booking) {
      return;
    }

    try {

      sessionStorage.setItem(
        CONFIRMATION_STORAGE_KEY,
        JSON.stringify(booking)
      );

    } catch (error) {

      console.error(
        "Unable to save confirmation booking:",
        error
      );

    }

  }, [booking]);


  // =========================================
  // NORMALISE SEATS
  // =========================================

  const normalizedSeats = useMemo(() => {

    if (
      !Array.isArray(
        booking?.seats
      )
    ) {
      return [];
    }

    return [
      ...new Set(

        booking.seats
          .map((seat) => {

            if (
              typeof seat === "object" &&
              seat !== null
            ) {

              return Number(
                seat.seat ??
                seat.seatNumber ??
                seat.number
              );

            }

            return Number(seat);

          })
          .filter(
            (seat) =>
              Number.isInteger(seat) &&
              seat > 0
          )

      )
    ];

  }, [booking]);


  // =========================================
  // PRICE VALUES
  // =========================================

  const totalPrice = Number(
    booking?.totalPrice ??
    booking?.total ??
    0
  );

  const discount = Number(
    booking?.discount ?? 0
  );

  const discountPercentage = Number(
    booking?.discountPercentage ??
    booking?.discount_percentage ??
    0
  );

  const totalPayment = Number(
    booking?.totalPayment ??
    Math.max(
      0,
      totalPrice - discount
    )
  );


  // =========================================
  // QR CODE DATA
  // =========================================

  const qrData = useMemo(() => {

    return `
BUSGO TICKET

${t("ticketNo")}: ${ticketNumber}

${t("passenger")}: ${booking?.name || ""}

${t("phone")}: ${booking?.phone || ""}

${t("route")}:
${booking?.from || ""} → ${booking?.to || ""}

${t("busType")}:
${booking?.busType || ""}

${t("seats")}:
${normalizedSeats.join(", ")}

${t("travelDate")}:
${booking?.date || ""}

${t("totalPrice")}:
XAF ${totalPrice.toLocaleString("en-GB")}

${t("discount")}:
XAF ${discount.toLocaleString("en-GB")}

${t("totalPayment")}:
XAF ${totalPayment.toLocaleString("en-GB")}

${t("paymentMethod")}:
${booking?.paymentMethod || ""}
`;

  }, [
    booking,
    ticketNumber,
    normalizedSeats,
    totalPrice,
    discount,
    totalPayment,
    t
  ]);


  // =========================================
  // CLEAR TEMPORARY CONFIRMATION DATA
  // =========================================

  const clearConfirmationStorage = () => {

    try {

      sessionStorage.removeItem(
        CONFIRMATION_STORAGE_KEY
      );

      sessionStorage.removeItem(
        TICKET_STORAGE_KEY
      );

    } catch (error) {

      console.error(
        "Unable to clear confirmation storage:",
        error
      );

    }

  };


  // =========================================
  // HANDLE AUTH SESSION EXPIRATION
  // =========================================

  const handleSessionExpired = () => {

    localStorage.removeItem(
      "loggedIn"
    );

    localStorage.removeItem(
      "currentUser"
    );

    localStorage.removeItem(
      "authToken"
    );

    navigate("/login");

  };


  // =========================================
  // CONFIRM BOOKING
  // =========================================

  const confirmBooking = async () => {

    if (saving) {
      return;
    }


    // =========================================
    // CHECK BOOKING
    // =========================================

    if (!booking) {

      alert(
        t("noBookingInformation")
      );

      navigate("/booking");

      return;

    }


    // =========================================
    // GET CURRENT USER
    // =========================================

    let currentUser = null;

    try {

      currentUser = JSON.parse(
        localStorage.getItem(
          "currentUser"
        ) || "null"
      );

    } catch {

      currentUser = null;

    }


    if (!currentUser?.id) {

      alert(
        t("loginBeforeConfirmation")
      );

      navigate("/login");

      return;

    }


    // =========================================
    // GET AUTH TOKEN
    // =========================================

    const authToken =
      localStorage.getItem(
        "authToken"
      );

    if (!authToken) {

      alert(
        t("sessionExpired")
      );

      handleSessionExpired();

      return;

    }


    // =========================================
    // VALIDATE ROUTE
    // =========================================

    if (
      !booking.from ||
      !booking.to
    ) {

      alert(
        t("routeInformationMissing")
      );

      return;

    }


    // =========================================
    // ROUTE ID
    // =========================================

    if (!booking.routeId) {

      alert(
        t("routeIdMissing")
      );

      return;

    }


    // =========================================
    // BUS TYPE
    // =========================================

    if (!booking.busType) {

      alert(
        t("busTypeMissing")
      );

      return;

    }


    // =========================================
    // BUS ID
    // =========================================

    if (!booking.busId) {

      alert(
        t("busInformationMissing")
      );

      return;

    }


    // =========================================
    // SEATS
    // =========================================

    if (
      normalizedSeats.length === 0
    ) {

      alert(
        t("noValidSeats")
      );

      return;

    }


    // =========================================
    // PASSENGER COUNT
    // =========================================

    const passengerCount =
      Number(
        booking.passengers ??
        normalizedSeats.length
      );

    if (
      !Number.isInteger(
        passengerCount
      ) ||
      passengerCount <= 0
    ) {

      alert(
        t("invalidPassengerCount")
      );

      return;

    }


    if (
      passengerCount !==
      normalizedSeats.length
    ) {

      alert(
        t("passengerSeatMismatch")
      );

      return;

    }


    // =========================================
    // DATE
    // =========================================

    if (!booking.date) {

      alert(
        t("travelDateMissing")
      );

      return;

    }


    // =========================================
    // PASSENGER NAME
    // =========================================

    if (
      !String(
        booking.name || ""
      ).trim()
    ) {

      alert(
        t("passengerNameMissing")
      );

      return;

    }


    // =========================================
    // PHONE
    // =========================================

    if (
      !String(
        booking.phone || ""
      ).trim()
    ) {

      alert(
        t("passengerPhoneMissing")
      );

      return;

    }


    // =========================================
    // PAYMENT METHOD
    // =========================================

    if (!booking.paymentMethod) {

      alert(
        t("paymentMethodMissing")
      );

      return;

    }


    // =========================================
    // PAYMENT AMOUNT
    // =========================================

    if (
      !Number.isFinite(
        totalPayment
      ) ||
      totalPayment <= 0
    ) {

      alert(
        t("invalidPaymentAmount")
      );

      return;

    }


    try {

      setSaving(true);


      console.log(
        "========================================="
      );

      console.log(
        "BUSGO CONFIRMATION"
      );

      console.log(
        "========================================="
      );

      console.log(
        "Booking data:",
        booking
      );

      console.log(
        "User ID:",
        currentUser.id
      );

      console.log(
        "Route ID:",
        booking.routeId
      );

      console.log(
        "Bus ID:",
        booking.busId
      );

      console.log(
        "Seats:",
        normalizedSeats
      );

      console.log(
        "Date:",
        booking.date
      );

      console.log(
        "Total Payment:",
        totalPayment
      );


      // =========================================
      // STEP 1
      // CREATE BOOKING
      // =========================================

      const bookingResponse =
        await axios.post(

          `${API_URL}/api/bookings`,

          {

            ticketNumber:
              ticketNumber,

            userId:
              currentUser.id,

            name:
              booking.name,

            phone:
              booking.phone,

            from:
              booking.from,

            to:
              booking.to,

            routeId:
              booking.routeId,

            busType:
              booking.busType,

            busId:
              booking.busId,

            seats:
              normalizedSeats,

            passengers:
              passengerCount,

            date:
              booking.date,

            totalPrice:
              totalPrice,

            discountPercentage:
              discountPercentage,

            discount:
              discount,

            totalPayment:
              totalPayment,

            offerId:
              booking.offerId ||
              null,

            offerTitle:
              booking.offerTitle ||
              "No Offer",

            paymentStatus:
              "Successful",

            paymentMethod:
              booking.paymentMethod,

            paymentDate:
              booking.paymentDate ||
              new Date().toISOString()

          }

        );


      console.log(
        "BOOKING RESPONSE:",
        bookingResponse.data
      );


      // =========================================
      // GET BOOKING ID
      // =========================================

      const bookingId =
        bookingResponse.data?.bookingId ||
        bookingResponse.data?.id ||
        bookingResponse.data?.booking?.id;


      if (!bookingId) {

        throw new Error(
          "Booking was created but the server did not return a booking ID."
        );

      }


      // =========================================
      // STEP 2
      // CREATE PAYMENT RECORD
      // =========================================

      const paymentResponse =
        await axios.post(

          `${API_URL}/api/payments`,

          {

            userId:
              currentUser.id,

            bookingId:
              bookingId,

            amount:
              totalPayment,

            currency:
              "XAF",

            paymentMethod:
              booking.paymentMethod,

            phoneNumber:
              booking.phone

          },

          {

            headers: {

              Authorization:
                `Bearer ${authToken}`

            }

          }

        );


      console.log(
        "PAYMENT RESPONSE:",
        paymentResponse.data
      );


      // =========================================
      // SUCCESS
      // =========================================

      setConfirmed(true);

      clearConfirmationStorage();


      setBooking(
        (currentBooking) => ({
          ...currentBooking,

          ticketNumber:
            ticketNumber,

          paymentStatus:
            "Successful",

          bookingStatus:
            "Confirmed",

          bookingId:
            bookingId

        })
      );


      alert(
        t("bookingPaymentSuccessful")
      );


      navigate(
        "/dashboard"
      );


    } catch (error) {

      console.error(
        "BUSGO BOOKING/PAYMENT ERROR",
        error
      );


      // =========================================
      // AUTHORIZATION ERROR
      // =========================================

      if (
        error.response?.status === 401
      ) {

        alert(
          t("sessionExpired")
        );

        handleSessionExpired();

        return;

      }


      // =========================================
      // SEAT CONFLICT
      // =========================================

      if (
        error.response?.status === 409
      ) {

        const conflictMessage =
          error.response.data?.message ||
          t("seatAlreadyBooked");


        const conflictSeats =
          error.response.data?.bookedSeats ||
          [];


        if (
          Array.isArray(
            conflictSeats
          ) &&
          conflictSeats.length > 0
        ) {

          alert(
            `${conflictMessage}\n\n${t("bookedSeats")}: ${conflictSeats.join(", ")}\n\n${t("selectAnotherSeat")}`
          );

        } else {

          alert(
            `${conflictMessage}\n\n${t("selectAnotherSeat")}`
          );

        }

        return;

      }


      // =========================================
      // SERVER ERROR
      // =========================================

      if (error.response) {

        const serverMessage =
          error.response.data?.message ||
          t("unableSaveBooking");


        const serverError =
          error.response.data?.error ||
          "";


        if (serverError) {

          alert(
            `${serverMessage}\n\n${serverError}`
          );

        } else {

          alert(
            serverMessage
          );

        }

        return;

      }


      // =========================================
      // NETWORK ERROR
      // =========================================

      alert(
        t("serverConnectionError")
      );

    } finally {

      setSaving(false);

    }

  };


  // =========================================
  // DOWNLOAD TICKET
  // =========================================

  const downloadTicket = async () => {

    const ticket =
      document.getElementById(
        "ticket"
      );


    if (!ticket) {

      alert(
        t("ticketNotFound")
      );

      return;

    }


    try {

      const canvas =
        await html2canvas(
          ticket,
          {
            scale: 2,
            useCORS: true,
            backgroundColor: "#ffffff"
          }
        );


      const imgData =
        canvas.toDataURL(
          "image/png"
        );


      const pdf =
        new jsPDF(
          "p",
          "mm",
          "a4"
        );


      const width = 190;


      const height =
        (
          canvas.height *
          width
        ) /
        canvas.width;


      pdf.addImage(
        imgData,
        "PNG",
        10,
        10,
        width,
        height
      );


      pdf.save(
        `BusGo-${ticketNumber}.pdf`
      );


    } catch (error) {

      console.error(
        "PDF download error:",
        error
      );

      alert(
        t("ticketDownloadError")
      );

    }

  };


  // =========================================
  // NO BOOKING
  // =========================================

  if (!booking) {

    return (

      <>

        <Navbar />

        <div className="empty-booking">

          <h2>
            {t("noBookingFound")}
          </h2>

          <p>
            {t("bookingNoLongerAvailable")}
          </p>

          <NavLink to="/booking">

            {t("makeBooking")}

          </NavLink>

        </div>

        <Footer />

      </>

    );

  }


  // =========================================
  // PAGE
  // =========================================

  return (

    <>

      <Navbar />


      <section className="ticket-page">


        {/* =====================================
            TICKET
        ===================================== */}

        <div
          className="ticket"
          id="ticket"
        >


          {/* HEADER */}

          <div className="ticket-header">

            <h1>
              BUSGO
            </h1>

            <p>
              {t("busTransportReservation")}
            </p>

          </div>


          {/* TICKET NUMBER */}

          <div className="ticket-number">

            {t("ticketNo")}:

            <strong>
              {ticketNumber}
            </strong>

          </div>


          {/* ROUTE */}

          <div className="route-box">

            <div>

              <small>
                {t("from").toUpperCase()}
              </small>

              <h2>
                {booking.from}
              </h2>

            </div>


            <span>
              →
            </span>


            <div>

              <small>
                {t("to").toUpperCase()}
              </small>

              <h2>
                {booking.to}
              </h2>

            </div>

          </div>


          {/* DETAILS */}

          <div className="details">


            {/* PASSENGER */}

            <p>

              <span>
                {t("passenger")}
              </span>

              {booking.name}

            </p>


            {/* PHONE */}

            <p>

              <span>
                {t("phone")}
              </span>

              {booking.phone}

            </p>


            {/* BUS */}

            <p>

              <span>
                {t("busType")}
              </span>

              {booking.busType}

            </p>


            {/* BUS ID */}

            {booking.busId && (

              <p>

                <span>
                  {t("busId")}
                </span>

                {booking.busId}

              </p>

            )}


            {/* SEATS */}

            <p>

              <span>
                {t("seats")}
              </span>

              {normalizedSeats.join(
                ", "
              ) || t("notSelected")}

            </p>


            {/* PASSENGERS */}

            <p>

              <span>
                {t("passengers")}
              </span>

              {booking.passengers ??
                normalizedSeats.length}

            </p>


            {/* DATE */}

            <p>

              <span>
                {t("travelDate")}
              </span>

              {booking.date}

            </p>


            {/* PAYMENT */}

            <p>

              <span>
                {t("payment")}
              </span>

              {booking.paymentMethod}

            </p>


            {/* OFFER */}

            {booking.offerTitle &&
              booking.offerTitle !==
                "No Offer" && (

              <p>

                <span>
                  {t("offer")}
                </span>

                <strong
                  className="offer-used"
                >

                  {booking.offerTitle}

                  {discountPercentage > 0 &&
                    ` (${discountPercentage}% ${t("off")})`}

                </strong>

              </p>

            )}


            {/* STATUS */}

            <p>

              <span>
                {t("status")}
              </span>

              <span className="paid">

                {confirmed
                  ? t("successful")
                  : t("readyForConfirmation")}

              </span>

            </p>


          </div>


          {/* PRICE BREAKDOWN */}

          <div className="ticket-price-breakdown">


            <div className="ticket-price-row">

              <span>
                {t("totalPrice")}
              </span>

              <strong>

                XAF{" "}

                {totalPrice.toLocaleString(
                  "en-GB"
                )}

              </strong>

            </div>


            <div
              className="
                ticket-price-row
                ticket-discount
              "
            >

              <span>

                {t("discount")}

                {discountPercentage > 0 &&
                  ` (${discountPercentage}%)`}

              </span>


              <strong>

                - XAF{" "}

                {discount.toLocaleString(
                  "en-GB"
                )}

              </strong>

            </div>


            <div
              className="
                ticket-price-divider
              "
            ></div>


            <div
              className="
                ticket-final-price
              "
            >

              <span>
                {t("totalPayment").toUpperCase()}
              </span>

              <h2>

                XAF{" "}

                {totalPayment.toLocaleString(
                  "en-GB"
                )}

              </h2>

            </div>


          </div>


          {/* QR CODE */}

          <div className="qr-box">

            <QRCodeCanvas

              value={qrData}

              size={120}

              bgColor="#ffffff"

              fgColor="#0b7d45"

            />

          </div>


          {/* THANK YOU */}

          <p className="thank">

            {t("thankYouBusGo")}

          </p>


        </div>


        {/* ACTION BUTTONS */}


        <button

          type="button"

          className="download-btn"

          onClick={
            downloadTicket
          }

        >

          {t("downloadTicketPdf")}

        </button>


        <button

          type="button"

          className="print-btn"

          onClick={() =>
            window.print()
          }

        >

          {t("printTicket")}

        </button>


        {!confirmed && (

          <button

            type="button"

            className="confirm-btn"

            onClick={
              confirmBooking
            }

            disabled={saving}

          >

            {saving
              ? t("savingBooking")
              : t("confirmBooking")}

          </button>

        )}


        {confirmed && (

          <button

            type="button"

            className="confirm-btn"

            onClick={() =>
              navigate(
                "/dashboard"
              )
            }

          >

            {t("goToDashboard")}

          </button>

        )}


      </section>


      <Footer />

    </>

  );

}


export default Confirmation;